    return (
    <>
    <Header />

    <main>
        <section className="contenido-inicio">
            <h1>Catálogo de productos</h1>  
            <p>Explora nuestros productos tejidos a mano, hechos con amor y dedicación</p>
        </section>
    </main>

    <Footer />
    </>
    );
    };

